// Проверяемое исключение для банковских операций
public class InsufficientFundsException extends Exception {

    public InsufficientFundsException(String message) {
        super(message);
    }

    public InsufficientFundsException(String message, Throwable cause) {
        super(message, cause);
    }
}

// Непроверяемое исключение для неверного возраста
public class InvalidAgeException extends RuntimeException {

    public InvalidAgeException(String message) {
        super(message);
    }
}

public class BankAccount {

    private double balance;

    public BankAccount(double balance) {
        this.balance = balance;
    }

    public void withdraw(double amount) throws InsufficientFundsException {
        if (amount > balance) {
            throw new InsufficientFundsException(
                "Недостаточно средств. Баланс: " + balance + ", запрошено: " + amount
            );
        }
        balance -= amount;
        System.out.println("Операция успешна. Остаток: " + balance);
    }

    public static void main(String[] args) {
        BankAccount account = new BankAccount(1000.0);

        try {
            account.withdraw(1500.0);
        } catch (InsufficientFundsException e) {
            System.out.println("Ошибка: " + e.getMessage());
        }
    }
}

public class AgeValidator {

    public void checkAge(int age) {
        // throw — выбрасываем исключение прямо здесь
        if (age < 0) {
